import React, { useState } from "react";
import "./ApplyForm.css";

export default function ApplyForm() {
  const [formData, setFormData] = useState({
    name: "",
    operatingRegion: "",
    cuisineType: ""
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const response = await fetch("http://localhost:8080/addVendor", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        throw new Error("Failed to submit");
      }

      alert("Vendor added successfully!");
      setFormData({ name: "", operatingRegion: "", cuisineType: "" });
    } catch (error) {
      console.error("Error submitting form", error);
      alert("Error adding vendor. Please try again.");
    }
  };

  return (
    <div className="apply-form-container">
      <form onSubmit={handleSubmit} className="apply-form">
        <h2>Apply as a Food Truck Vendor</h2>

        <input
          name="name"
          value={formData.name}
          onChange={handleChange}
          placeholder="Vendor Name"
          required
        />

        <input
          name="operatingRegion"
          value={formData.operatingRegion}
          onChange={handleChange}
          placeholder="Operating Region"
          required
        />

        <input
          name="cuisineType"
          value={formData.cuisineType}
          onChange={handleChange}
          placeholder="Cuisine Type"
          required
        />

        <button type="submit">Submit Application</button>
      </form>
    </div>
  );
}
